public class Main {
    public static void main(String[] args) {
        int m1 = 88, m2 = 92, m3 = 90;
        double avg = (double)(m1 + m2 + m3) / 3;
        int grant = (avg >= 90) ? 20000 : 5000;
        System.out.println("Average: " + avg + "% | Scholarship: Rs " + grant);
    }
}

